type CardContent = {
  readonly suggestion: ReadySuggestion
  readonly showRationale: boolean
  readonly showActions: boolean
}

type CardKind = 'active' | 'hover'

const contentFor = (
  kind: CardKind,
  state: EditorState,
): CardContent | undefined => {
  const hoveredId = state.field(interactionField).hoveredId
  const active = activeOf(state)
  if (kind === 'active') {
    if (!active) return undefined
    const cursorInside =
      active.from <= cursorOf(state) && cursorOf(state) <= active.to
    return {
      suggestion: active,
      showRationale: cursorInside || hoveredId === active.id,
      showActions: true,
    }
  }
  if (hoveredId === null || hoveredId === active?.id) return undefined
  const hovered = findSuggestion(suggestionsOf(state), hoveredId)
  return hovered?.status === 'ready'
    ? { suggestion: hovered, showRationale: true, showActions: false }
    : undefined
}

const contentKey = ({
  suggestion,
  showRationale,
  showActions,
}: CardContent): string =>
  [suggestion.id, suggestion.rationale, showRationale, showActions].join(
    '\u0000',
  )

const shortcutLabel = (key: string): string =>
  formatShortcut(key, detectApplePlatform())

const actionButton = (
  view: EditorView,
  label: string,
  hint: string,
  run: () => void,
) =>
  el(
    'button',
    {
      class: 'cm-ai-button',
      attrs: { type: 'button' },
      on: {
        mousedown: (event) => event.preventDefault(),
        click: () => {
          run()
          view.focus()
        },
      },
    },
    [label, el('kbd', { class: 'cm-ai-kbd' }, [hint])],
  )

const renderCard = (view: EditorView, content: CardContent): Node[] => {
  const { suggestion, showRationale, showActions } = content
  return [
    ...(showRationale
      ? [el('p', { class: 'cm-ai-rationale' }, [suggestion.rationale])]
      : []),
    ...(showActions
      ? [
          el('div', { class: 'cm-ai-card-actions' }, [
            actionButton(view, 'Accept', shortcutLabel('↵'), () =>
              acceptSuggestionById(view, suggestion.id),
            ),
            actionButton(view, 'Reject', 'Esc', () =>
              rejectSuggestionById(view, suggestion.id),
            ),
          ]),
        ]
      : []),
  ]
}

const cardCreator =
  (kind: CardKind) =>
  (view: EditorView): TooltipView => {
    const dom = el('div', {
      class: `cm-ai-card cm-ai-card-${kind}`,
      attrs:
        kind === 'active' ? { role: 'group', 'aria-label': 'Suggestion' } : {},
    })
    let renderedKey = ''
    const sync = (state: EditorState): void => {
      const content = contentFor(kind, state)
      if (!content) return
      const key = contentKey(content)
      if (key === renderedKey) return
      renderedKey = key
      dom.replaceChildren(...renderCard(view, content))
    }
    sync(view.state)
    return { dom, update: (update) => sync(update.state) }
  }

const createActiveCard = cardCreator('active')
const createHoverCard = cardCreator('hover')

const tooltipFor = (
  kind: CardKind,
  state: EditorState,
  create: (view: EditorView) => TooltipView,
): Tooltip | null => {
  const content = contentFor(kind, state)
  return content ? { pos: content.suggestion.from, above: true, create } : null
}

export const suggestionCards = showTooltip.computeN(
  [suggestionsField, interactionField, 'selection'],
  (state) => [
    tooltipFor('active', state, createActiveCard),
    tooltipFor('hover', state, createHoverCard),
  ],
)
import { Prec } from '@codemirror/state'
import { type Command, keymap } from '@codemirror/view'
import { bubbleVisible, dismissBubbleEffect, openAskEffect } from './ask-bubble'
import { currentTarget } from './current-target'
import {
  acceptAtCursor,
  type EditorHandle,
  rejectAtCursor,
} from './suggestion-commands'

const openAsk: Command = (view) => {
  if (currentTarget(view.state) === undefined) return false
  view.dispatch({ effects: openAskEffect.of(null) })
  return true
}

const dismissBubble = (handle: EditorHandle): boolean => {
  if (!bubbleVisible(handle.state)) return false
  handle.dispatch({ effects: dismissBubbleEffect.of(null) })
  return true
}

export const escapeAtCursor = (handle: EditorHandle): boolean =>
  dismissBubble(handle) || rejectAtCursor(handle)

export const suggestionKeymap = Prec.highest(
  keymap.of([
    { key: 'Mod-k', run: openAsk, preventDefault: true },
    { key: 'Mod-Enter', run: acceptAtCursor },
    { key: 'Escape', run: escapeAtCursor },
  ]),
)
import { isolateHistory } from '@codemirror/commands'
import type { EditorState, TransactionSpec } from '@codemirror/state'
import { findSuggestion } from '../suggestions/state'
import type { SuggestionId } from '../suggestions/types'
import {
  acceptEffect,
  rejectEffect,
  suggestionAtCursor,
  suggestionsOf,
} from './suggestion-field'

export type EditorHandle = {
  readonly state: EditorState
  readonly dispatch: (spec: TransactionSpec) => void
}

export const acceptSuggestionById = (
  handle: EditorHandle,
  id: SuggestionId,
): boolean => {
  const found = findSuggestion(suggestionsOf(handle.state), id)
  if (found?.status !== 'ready') return false
  handle.dispatch({
    changes: { from: found.from, to: found.to, insert: found.replacement },
    selection: { anchor: found.from + found.replacement.length },
    effects: acceptEffect.of(found.id),
    annotations: isolateHistory.of('full'),
    userEvent: 'input.accept',
    scrollIntoView: true,
  })
  return true
}

export const rejectSuggestionById = (
  handle: EditorHandle,
  id: SuggestionId,
): boolean => {
  if (findSuggestion(suggestionsOf(handle.state), id) === undefined)
    return false
  handle.dispatch({ effects: rejectEffect.of(id) })
  return true
}

export const acceptAtCursor = (handle: EditorHandle): boolean => {
  const found = suggestionAtCursor(handle.state)
  if (found === undefined) return false
  if (found.status === 'ready') acceptSuggestionById(handle, found.id)
  return true
}

export const rejectAtCursor = (handle: EditorHandle): boolean => {
  const found = suggestionAtCursor(handle.state)
  return found === undefined ? false : rejectSuggestionById(handle, found.id)
}
