import type { Block } from '../blocks/extract-blocks'
import type { ReviewEdit, SuggestionOutput } from './schemas'

export const MAX_REVIEW_EDITS = 6

export type DropReason =
  | 'unknown-block'
  | 'code-block'
  | 'occupied'
  | 'duplicate-block'
  | 'empty'
  | 'unchanged'
  | 'over-limit'

export type ValidatedEdit = ReviewEdit & { readonly block: Block }

export type DroppedEdit = {
  readonly edit: ReviewEdit
  readonly reason: DropReason
}

export type ReviewValidationState = {
  readonly validated: number
  readonly seen: ReadonlySet<string>
}

export type ReviewValidationContext = {
  readonly blocks: readonly Block[]
  readonly occupied: ReadonlySet<string>
}

export type ReviewOutcome =
  | { readonly type: 'validated'; readonly edit: ValidatedEdit }
  | ({ readonly type: 'dropped' } & DroppedEdit)

export const initialReviewState: ReviewValidationState = {
  validated: 0,
  seen: new Set(),
}

const dropReason = (
  occupied: ReadonlySet<string>,
  state: ReviewValidationState,
  edit: ReviewEdit,
  block: Block | undefined,
): DropReason | undefined => {
  if (block === undefined) return 'unknown-block'
  if (block.kind === 'code') return 'code-block'
  if (occupied.has(block.id)) return 'occupied'
  if (state.seen.has(block.id)) return 'duplicate-block'
  const replacement = edit.replacement.trim()
  if (replacement === '') return 'empty'
  if (replacement === block.text.trim()) return 'unchanged'
  if (state.validated >= MAX_REVIEW_EDITS) return 'over-limit'
  return undefined
}

export const validateReviewEdit = (
  context: ReviewValidationContext,
  state: ReviewValidationState,
  edit: ReviewEdit,
): {
  readonly state: ReviewValidationState
  readonly outcome: ReviewOutcome
} => {
  const block = context.blocks.find(
    (candidate) => candidate.id === edit.blockId,
  )
  const reason = dropReason(context.occupied, state, edit, block)
  if (reason !== undefined || block === undefined) {
    return {
      state,
      outcome: { type: 'dropped', edit, reason: reason ?? 'unknown-block' },
    }
  }
  return {
    state: {
      validated: state.validated + 1,
      seen: new Set([...state.seen, block.id]),
    },
import { type EditorState, StateEffect, StateField } from '@codemirror/state'
import type { SuggestionResult } from '../ai/edits'
import type { ClientError } from '../ai/errors'
import {
  acceptSuggestion,
  activeSuggestion,
  beginSuggestion,
  emptySuggestions,
  failSuggestion,
  mapSuggestions,
  rejectSuggestion,
  resolveSuggestion,
  retrySuggestion,
  suggestionAt,
} from '../suggestions/state'
import type {
  ReadySuggestion,
  Suggestion,
  SuggestionDraft,
  SuggestionId,
  SuggestionsState,
} from '../suggestions/types'

export const beginEffect = StateEffect.define<SuggestionDraft>()
export const resolveEffect = StateEffect.define<{
  readonly id: SuggestionId
  readonly result: SuggestionResult
}>()
export const failEffect = StateEffect.define<{
  readonly id: SuggestionId
  readonly error: ClientError
}>()
export const retryEffect = StateEffect.define<SuggestionId>()
export const rejectEffect = StateEffect.define<SuggestionId>()
export const acceptEffect = StateEffect.define<SuggestionId>()

const applyEffect = (
  state: SuggestionsState,
  effect: StateEffect<unknown>,
): SuggestionsState => {
  if (effect.is(beginEffect)) return beginSuggestion(state, effect.value)
  if (effect.is(resolveEffect))
    return resolveSuggestion(state, effect.value.id, effect.value.result)
  if (effect.is(failEffect))
    return failSuggestion(state, effect.value.id, effect.value.error)
  if (effect.is(retryEffect)) return retrySuggestion(state, effect.value)
  if (effect.is(rejectEffect)) return rejectSuggestion(state, effect.value)
  return state
}

export const suggestionsField = StateField.define<SuggestionsState>({
  create: () => emptySuggestions,
  update: (value, transaction) => {
    const accepted = transaction.effects.find((effect) =>
      effect.is(acceptEffect),
    )
    const mapped = accepted
      ? acceptSuggestion(value, accepted.value, transaction.changes)
      : mapSuggestions(value, transaction.changes)
    return transaction.effects.reduce(applyEffect, mapped)
  },
})

export const suggestionsOf = (state: EditorState): SuggestionsState =>
  state.field(suggestionsField)

export const cursorOf = (state: EditorState): number =>
  state.selection.main.head

export const activeOf = (state: EditorState): ReadySuggestion | undefined =>
  activeSuggestion(suggestionsOf(state), cursorOf(state))

export const suggestionAtCursor = (
  state: EditorState,
): Suggestion | undefined => suggestionAt(suggestionsOf(state), cursorOf(state))
import { type EditorState, Facet } from '@codemirror/state'
import { ViewPlugin } from '@codemirror/view'
import type { ModelClient } from '../ai/client'
import { getNeighbors, targetFromRange } from '../blocks/target'
import { taskLabel } from '../suggestions/instruction'
import { findSuggestion, pendingSuggestionIds } from '../suggestions/state'
import type { Instruction, SuggestionId } from '../suggestions/types'
import { blocksOf, currentTarget, textOf } from './current-target'
import type { EditorHandle } from './suggestion-commands'
import {
  beginEffect,
  failEffect,
  resolveEffect,
  retryEffect,
  suggestionsField,
  suggestionsOf,
} from './suggestion-field'

export type SuggestionActions = {
  readonly ask: (handle: EditorHandle, instruction: Instruction) => void
  readonly retry: (handle: EditorHandle, id: SuggestionId) => void
}

export const suggestionActionsFacet = Facet.define<
  SuggestionActions,
  SuggestionActions | undefined
>({ combine: (values) => values.at(-1) })

type RuntimeOptions = {
  readonly client: Pick<ModelClient, 'requestSuggestion'>
  readonly createId?: () => SuggestionId
}

export const createSuggestionRuntime = ({
  client,
  createId = (() => {
    let counter = 0
    return () => `s${++counter}`
  })(),
}: RuntimeOptions) => {
  const controllers = new Map<SuggestionId, AbortController>()

  const reconcile = (state: EditorState): void => {
    const pending = new Set(pendingSuggestionIds(suggestionsOf(state)))
    for (const [id, controller] of controllers) {
      if (pending.has(id)) continue
      controller.abort()
      controllers.delete(id)
    }
  }

  const run = async (
    handle: EditorHandle,
    id: SuggestionId,
    request: Parameters<typeof client.requestSuggestion>[0],
  ): Promise<void> => {
    const controller = new AbortController()
    controllers.set(id, controller)
    const result = await client.requestSuggestion({
      ...request,
      signal: controller.signal,
    })
    if (controllers.get(id) === controller) controllers.delete(id)
    if (controller.signal.aborted) return
    handle.dispatch({
      effects: result.ok
        ? resolveEffect.of({ id, result: result.value })
        : failEffect.of({ id, error: result.error }),
    })
  }

  const ask = (handle: EditorHandle, instruction: Instruction): void => {
    const { state } = handle
    const target = currentTarget(state)
    if (!target) return
    const id = createId()
    handle.dispatch({
      effects: beginEffect.of({
        id,
        from: target.from,
        to: target.to,
        source: target.source,
        original: target.text,
        instruction,
      }),
      ...(target.source === 'selection' && {
        selection: { anchor: target.to },
      }),
    })
    void run(handle, id, {
      target,
      neighbors: getNeighbors(blocksOf(state), target),
      instruction: instruction.text,
      task: taskLabel({
        source: target.source,
        blocks: target.blocks,
        instruction,
      }),
    })
  }

  const retry = (handle: EditorHandle, id: SuggestionId): void => {
    const { state } = handle
    const found = findSuggestion(suggestionsOf(state), id)
    if (found?.status !== 'error') return
    const blocks = blocksOf(state)
    const target = targetFromRange(blocks, textOf(state), found, found.source)
    handle.dispatch({ effects: retryEffect.of(id) })
    void run(handle, id, {
      target,
      neighbors: getNeighbors(blocks, target),
      instruction: found.instruction.text,
      task: taskLabel({
        source: found.source,
        blocks: target.blocks,
        instruction: found.instruction,
      }),
    })
  }

  const actions: SuggestionActions = { ask, retry }

  const extension = [
    suggestionActionsFacet.of(actions),
    ViewPlugin.define(() => ({
      update: (update) => {
        if (
          update.startState.field(suggestionsField) !==
          update.state.field(suggestionsField)
        ) {
          reconcile(update.state)
        }
      },
      destroy: () => {
        for (const controller of controllers.values()) controller.abort()
        controllers.clear()
      },
    })),
  ]

  return { actions, extension, reconcile }
}

