import {
  type ChangeDesc,
  type EditorState,
  StateEffect,
  StateField,
} from '@codemirror/state'
import {
  type EditorView,
  showTooltip,
  type Tooltip,
  type TooltipView,
} from '@codemirror/view'
import { QUICK_ACTIONS } from '../ai/quick-actions'
import {
  freeTextInstruction,
  quickActionInstruction,
} from '../suggestions/instruction'
import { currentTarget } from './current-target'
import { el } from './dom'
import { interactionField } from './interaction-state'
import { beginEffect } from './suggestion-field'
import { suggestionActionsFacet } from './suggestion-runtime'

type Range = { readonly from: number; readonly to: number }

type BubbleState = {
  readonly askOpen: boolean
  readonly dismissed: Range | null
}

export const openAskEffect = StateEffect.define<null>()
export const dismissBubbleEffect = StateEffect.define<null>()

const sameRange = (a: Range | null, b: Range): boolean =>
  a !== null && a.from === b.from && a.to === b.to

const mapRange = (range: Range, changes: ChangeDesc): Range => ({
  from: changes.mapPos(range.from, 1),
  to: changes.mapPos(range.to, -1),
})

export const bubbleField = StateField.define<BubbleState>({
  create: () => ({ askOpen: false, dismissed: null }),
  update: (value, transaction) => {
    const selection = transaction.state.selection.main
    const moved =
      transaction.docChanged ||
      !transaction.startState.selection.main.eq(selection)
    const opened = transaction.effects.some((effect) =>
      effect.is(openAskEffect),
    )
    const closed = transaction.effects.some(
      (effect) => effect.is(dismissBubbleEffect) || effect.is(beginEffect),
    )
    const mapped =
      value.dismissed && transaction.docChanged
        ? mapRange(value.dismissed, transaction.changes)
        : value.dismissed
    const askOpen = closed ? false : opened ? true : value.askOpen && !moved
    const dismissed = closed
      ? { from: selection.from, to: selection.to }
      : sameRange(mapped, selection)
        ? mapped
        : null
    return { askOpen, dismissed }
  },
})

export const bubbleVisible = (state: EditorState): boolean => {
  const { askOpen, dismissed } = state.field(bubbleField)
  const { focused, pointerDown } = state.field(interactionField)
  if (!focused) return false
  if (askOpen) return currentTarget(state) !== undefined
  const selection = state.selection.main
  return (
    !pointerDown &&
    !selection.empty &&
    !sameRange(dismissed, selection) &&
    currentTarget(state) !== undefined
  )
}

const isAsking = (state: EditorState): boolean =>
  state.field(bubbleField).askOpen

export const targetPreviewRange = (state: EditorState): Range | undefined => {
  if (!isAsking(state) || !state.selection.main.empty) return undefined
  return currentTarget(state)
}

const buildBubble = (view: EditorView) => {
  const actions = () => view.state.facet(suggestionActionsFacet)

  const input = el('input', {
    class: 'cm-ai-bubble-input',
    attrs: {
      type: 'text',
      placeholder: 'Ask AI…',
      'aria-label': 'Ask AI',
      autocomplete: 'off',
      spellcheck: 'false',
    },
    on: {
      keydown: (event) => {
        if (event.key === 'Escape') {
          event.preventDefault()
          event.stopPropagation()
          input.value = ''
          view.dispatch({ effects: dismissBubbleEffect.of(null) })
          view.focus()
        } else if (event.key === 'k' && (event.metaKey || event.ctrlKey)) {
          event.preventDefault()
        }
      },
    },
  })

  const form = el(
    'form',
    {
      class: 'cm-ai-bubble-ask',
      on: {
        submit: (event) => {
          event.preventDefault()
          const text = input.value.trim()
          if (text === '') return
          input.value = ''
          actions()?.ask(view, freeTextInstruction(text))
          view.focus()
        },
      },
    },
    [input],
  )

  const buttons = QUICK_ACTIONS.map((action) =>
    el(
      'button',
      {
        class: 'cm-ai-chip',
        attrs: { type: 'button' },
        on: {
          mousedown: (event) => event.preventDefault(),
          click: () => {
            actions()?.ask(view, quickActionInstruction(action.id))
            view.focus()
          },
        },
      },
      [action.label],
    ),
  )

  const dom = el(
    'div',
    {
      class: 'cm-ai-bubble',
      attrs: { role: 'group', 'aria-label': 'Ask AI' },
      on: {
        mousedown: (event) => {
          if (event.target !== input) event.preventDefault()
        },
      },
    },
    [
      el(
        'div',
        { class: 'cm-ai-bubble-actions', attrs: { role: 'toolbar' } },
        buttons,
      ),
      form,
    ],
  )

  const focusIfAsking = (state: EditorState): void => {
    if (isAsking(state)) input.focus()
  }

  const tooltipView: TooltipView = {
    dom,
    mount: () => focusIfAsking(view.state),
    update: (update) => {
      const reopened = update.transactions.some((transaction) =>
        transaction.effects.some((effect) => effect.is(openAskEffect)),
      )
      if (reopened) focusIfAsking(update.state)
    },
  }
  return tooltipView
}

const bubbleTooltip = (state: EditorState): Tooltip | null => {
  if (!bubbleVisible(state)) return null
  const target = currentTarget(state)
  return target ? { pos: target.from, above: true, create: buildBubble } : null
}

export const askBubble = [
  bubbleField,
  showTooltip.compute(
    [bubbleField, interactionField, 'selection', 'doc'],
    bubbleTooltip,
  ),
]
import type { EditorState, Range } from '@codemirror/state'
import {
  Decoration,
  type DecorationSet,
  EditorView,
  WidgetType,
} from '@codemirror/view'
import { describeError } from '../suggestions/error-message'
import type {
  ReadySuggestion,
  Suggestion,
  SuggestionId,
} from '../suggestions/types'
import { bubbleField, targetPreviewRange } from './ask-bubble'
import { el } from './dom'
import { rejectSuggestionById } from './suggestion-commands'
import { activeOf, suggestionsField, suggestionsOf } from './suggestion-field'
import { suggestionActionsFacet } from './suggestion-runtime'

const idAttributes = (id: SuggestionId) => ({ 'data-suggestion-id': id })

class InsertedWidget extends WidgetType {
  constructor(
    readonly id: SuggestionId,
    readonly text: string,
    readonly separated: boolean,
  ) {
    super()
  }

  eq(other: InsertedWidget): boolean {
    return (
      other.id === this.id &&
      other.text === this.text &&
      other.separated === this.separated
    )
  }

  toDOM(): HTMLElement {
    return el(
      'ins',
      {
        class: `cm-ai-inserted${this.separated ? ' cm-ai-inserted-separated' : ''}`,
        attrs: idAttributes(this.id),
      },
      [this.text],
    )
  }

  ignoreEvent(): boolean {
    return false
  }
}

class ReplacementWidget extends WidgetType {
  constructor(
    readonly id: SuggestionId,
    readonly text: string,
  ) {
    super()
  }

  eq(other: ReplacementWidget): boolean {
    return other.id === this.id && other.text === this.text
  }

  toDOM(): HTMLElement {
    return el(
      'div',
      {
        class: 'cm-ai-replacement',
        attrs: idAttributes(this.id),
      },
      [el('ins', {}, [this.text])],
    )
  }

  ignoreEvent(): boolean {
    return false
  }
}

class ErrorCardWidget extends WidgetType {
  constructor(
    readonly id: SuggestionId,
    readonly message: string,
  ) {
    super()
  }

  eq(other: ErrorCardWidget): boolean {
    return other.id === this.id && other.message === this.message
  }

  toDOM(view: EditorView): HTMLElement {
    const button = (label: string, onClick: () => void) =>
      el(
        'button',
        {
          class: 'cm-ai-button',
          attrs: { type: 'button' },
          on: {
            mousedown: (event) => event.preventDefault(),
            click: () => {
              onClick()
              view.focus()
            },
          },
        },
        [label],
      )
    return el(
      'div',
      {
        class: 'cm-ai-error',
        attrs: { role: 'alert', ...idAttributes(this.id) },
      },
      [
        el('span', { class: 'cm-ai-error-message' }, [this.message]),
        el('span', { class: 'cm-ai-error-actions' }, [
          button('Retry', () =>
            view.state.facet(suggestionActionsFacet)?.retry(view, this.id),
          ),
          button('Dismiss', () => rejectSuggestionById(view, this.id)),
        ]),
      ],
    )
  }

  ignoreEvent(): boolean {
    return true
  }
}

const pendingMark = (id: SuggestionId) =>
  Decoration.mark({
    class: 'cm-ai-pending',
    attributes: idAttributes(id),
  })

const failedMark = (id: SuggestionId) =>
  Decoration.mark({
    class: 'cm-ai-failed',
    attributes: idAttributes(id),
  })

const suggestionMark = (id: SuggestionId, active: boolean) =>
  Decoration.mark({
    class: active ? 'cm-ai-suggestion cm-ai-active' : 'cm-ai-suggestion',
    attributes: idAttributes(id),
  })

const deletedMark = (id: SuggestionId) =>
  Decoration.mark({
    tagName: 'del',
    class: 'cm-ai-deleted',
    attributes: idAttributes(id),
  })

const readyRanges = (
  suggestion: ReadySuggestion,
  active: boolean,
): readonly Range<Decoration>[] => {
  const { id, from, to, diff } = suggestion
  const hunks = diff.hunks.flatMap((hunk, index): Range<Decoration>[] => {
    if (hunk.type === 'deleted') {
      return hunk.from === hunk.to
        ? []
        : [deletedMark(id).range(from + hunk.from, from + hunk.to)]
    }
    if (hunk.type !== 'inserted') return []
    if (diff.mode === 'block') {
      return [
        Decoration.widget({
          widget: new ReplacementWidget(id, hunk.text),
          block: true,
          side: 1,
        }).range(to),
      ]
    }
    const separated = diff.hunks[index - 1]?.type === 'deleted'
    return [
      Decoration.widget({
        widget: new InsertedWidget(id, hunk.text, separated),
        side: 1,
      }).range(from + hunk.at),
    ]
  })
  return [suggestionMark(id, active).range(from, to), ...hunks]
}

const suggestionRanges = (
  suggestion: Suggestion,
  active: boolean,
): readonly Range<Decoration>[] => {
  switch (suggestion.status) {
    case 'pending':
      return [pendingMark(suggestion.id).range(suggestion.from, suggestion.to)]
    case 'error':
      return [
        failedMark(suggestion.id).range(suggestion.from, suggestion.to),
        Decoration.widget({
          widget: new ErrorCardWidget(
            suggestion.id,
            describeError(suggestion.error),
          ),
          block: true,
          side: 1,
        }).range(suggestion.to),
      ]
    case 'ready':
      return readyRanges(suggestion, active)
  }
}

const targetPreview = Decoration.mark({ class: 'cm-ai-target-preview' })

export const buildDecorations = (state: EditorState): DecorationSet => {
  const active = activeOf(state)
  const preview = targetPreviewRange(state)
  return Decoration.set(
    [
      ...suggestionsOf(state).items.flatMap((suggestion) =>
        suggestionRanges(suggestion, suggestion.id === active?.id),
      ),
